131→
132→  /** 读取资源字节；不存在 → null。 */
133→  async readResource(
134→    skillId: string,
135→    version: number,
136→    path: string,
137→    encoding: "utf-8" | "base64",
138→  ): Promise<SkillResourceReadResult | null> {
139→    this.assertPath(path);
140→    const key = this.fileKey(skillId, version, path);
141→    const buf = await this.storage.readFileBuffer(key);
142→    if (!buf) return null;
143→    return {
144→      path,
145→      content: encoding === "base64" ? buf.toString("base64") : buf.toString("utf-8"),
146→      encoding,
147→      size_bytes: buf.length,
148→      mime_type: guessMime(path),
149→      is_executable: false, // 不从 storage 元数据反推（local-fs 与 COS 行为不一致）
150→      version,
151→    };
152→  }
153→
154→  /** 删除资源（幂等：不存在不抛错）。 */
155→  async removeResource(skillId: string, version: number, path: string): Promise<void> {
156→    this.assertPath(path);
157→    const key = this.fileKey(skillId, version, path);
158→    try {
159→      await this.storage.unlink(key);
160→    } catch {
161→      /* idempotent */
162→    }
163→  }
164→
165→  /** 列出某版本目录下的全部资源元信息（不含字节）。 */
166→  async listResources(skillId: string, version: number): Promise<SkillManifestEntry[]> {
167→    const prefix = this.filesPrefix(skillId, version);
168→    const result = await this.storage.getBackend().listObjects(prefix, {
169→      recursive: true,
170→      maxKeys: 100_000,
171→    });
172→    const out: SkillManifestEntry[] = [];
173→    for (const e of result.entries) {
174→      if (e.isDirectory) continue;
175→      const path = e.key.startsWith(prefix) ? e.key.slice(prefix.length) : e.key;
176→      // 读元数据拿到 is_executable / contentType（开销比读字节小很多）
177→      const obj = await this.storage.getBackend().getObject(e.key);
178→      const isExec = obj?.metadata?.is_executable === "1";
179→      const mime = obj?.contentType ?? guessMime(path);
180→      out.push({
181→        path,
182→        size_bytes: e.size,
183→        mime_type: mime,
184→        is_executable: isExec,
185→      });
186→    }
187→    return out;
188→  }
189→
190→  /** 拿到该版本目录的相对前缀，便于 skill-versioning 调 storage.copyTree。 */
191→  versionDir(skillId: string, version: number): string {
192→    return `${STORAGE_PREFIX}${skillId}/v${version}`;
193→  }
194→
195→  // ── helpers ──
196→
197→  private fileKey(skillId: string, version: number, path: string): string {
198→    return `${this.filesPrefix(skillId, version)}${path}`;
199→  }
